import React, { useState, useRef, useEffect, useMemo } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { useHistory } from '../contexts/HistoryContext';
import { useAuth } from '../contexts/AuthContext';
import { usePrayer } from '../contexts/PrayerContext';
import { useToast } from '../contexts/ToastContext'; 
import { getAllSurahs } from '../services/quranApiService';
import { getHadithBooks } from '../services/hadithApiService';
import { 
  Sparkles, History as HistoryIcon, MapPin, GraduationCap, Brain, Activity, Compass, Calendar, Coins, Calculator, HeartHandshake, Keyboard, ArrowRight, Search, X, Book, BookOpen, Scroll, Settings, User, Clock, Tv, LayoutGrid, Trophy, Mic, RefreshCw, Quote, Video, Share2, PlayCircle, Loader2, Library, Radio, BookHeart, CalendarClock, Star, Droplets, Map, Moon, Baby, Disc, MessageSquare, Newspaper, ImageIcon, UserX
} from 'lucide-react';
import HistoryScreen from './HistoryScreen';
import { MutiaraData } from '../types'; // Import MutiaraData interface
import { QUOTE_THEMES } from '../services/geminiService'; 
import { fetchNewsReleases, fetchTrendingTopics, fetchPublicMutiara } from '../services/supabaseService'; // NEW: fetchPublicMutiara from Supabase

interface HomeScreenProps { fontSize: number; }

const ISLAMIC_EVENTS = [
  { name: 'Tahun Baru Hijriyah', month: 1, day: 1 },
  { name: 'Maulid Nabi SAW', month: 3, day: 12 },
  { name: 'Isra Mi\'raj', month: 7, day: 27 },
  { name: 'Awal Ramadhan', month: 9, day: 1 },
  { name: 'Nuzulul Qur\'an', month: 9, day: 17 },
  { name: 'Idul Fitri', month: 10, day: 1 },
  { name: 'Idul Adha', month: 12, day: 10 },
];

// 8 Kotak Grid Utama
const MAIN_FEATURES = [ 
  { id: 'mawdhui', icon: Library, label: "Studi Mawdhui", path: "/mawdhui-study", color: "bg-opacity-20 bg-indigo-100 text-indigo-600 border-indigo-200" }, 
  { id: 'tahfidz', icon: Mic, label: "Tahfidz", path: "/tahfidz", color: "bg-opacity-20 bg-emerald-100 text-emerald-600 border-emerald-200" }, 
  { id: 'doa', icon: HeartHandshake, label: "Doa-doa", path: "/doa", color: "bg-opacity-20 bg-cyan-100 text-cyan-600 border-cyan-200" }, 
  { id: 'media', icon: Disc, label: "Media", color: "bg-opacity-20 bg-blue-100 text-blue-600 border-blue-200" }, 
  { id: 'wanita', icon: Moon, label: "Wanita", color: "bg-opacity-20 bg-rose-100 text-rose-600 border-rose-200" }, 
  { id: 'hitung', icon: Calculator, label: "Hitung Umum", color: "bg-opacity-20 bg-amber-100 text-amber-600 border-amber-200" }, 
  { id: 'top', icon: Trophy, label: "Top Santri", path: "/leaderboard", color: "bg-opacity-20 bg-yellow-100 text-yellow-600 border-yellow-200" }, 
  { id: 'more', icon: LayoutGrid, label: "Lainnya", color: "bg-opacity-20 bg-slate-100 text-slate-600 border-slate-200" }, 
];

// Sub-menu Data
const SUB_FEATURES: Record<string, any[]> = {
  media: [
    { icon: Disc, label: "Playlist Mp3", color: "bg-blue-100 text-blue-600 border-blue-200", path: "/playlist" },
    { icon: Tv, label: "TV Mekkah", color: "bg-red-100 text-red-600 border-red-200", path: "/tv-mekkah" }, 
    { icon: Radio, label: "Radio Islami", color: "bg-teal-100 text-teal-600 border-teal-200", path: "/radio" }, 
  ],
  wanita: [
    { icon: Moon, label: "Hitung Haid", color: "bg-rose-100 text-rose-600 border-rose-200", path: "/haid" },
    { icon: Baby, label: "Hitung Nifas", color: "bg-pink-100 text-pink-600 border-pink-200", path: "/nifas" },
    { icon: Clock, label: "Masa Iddah", color: "bg-violet-100 text-violet-600 border-violet-200", path: "/iddah" },
  ],
  hitung: [
    { icon: Activity, label: "Tasbih", color: "bg-teal-100 text-teal-600 border-teal-200", path: "/tasbih" }, 
    { icon: Calculator, label: "Waris", color: "bg-pink-100 text-pink-600 border-pink-200", path: "/waris" }, 
    { icon: Coins, label: "Hitung Zakat", color: "bg-emerald-100 text-emerald-600 border-emerald-200", path: "/zakat" }, 
    { icon: UserX, label: "Kematian", color: "bg-slate-100 text-slate-600 border-slate-200", path: "/death-anniversary" },
    { icon: Droplets, label: "Cek 2 Qullah", color: "bg-cyan-100 text-cyan-600 border-cyan-200", path: "/water" },
    { icon: Map, label: "Jarak Safar", color: "bg-blue-100 text-blue-600 border-blue-200", path: "/travel" },
    { icon: Compass, label: "Arah Kiblat", color: "bg-blue-100 text-blue-600 border-blue-200", path: "/qibla" }, 
    { icon: Calendar, label: "Kalender", color: "bg-orange-100 text-orange-600 border-orange-200", path: "/calendar" }, 
  ],
  more: [
    { icon: GraduationCap, label: "Latihan Baca", color: "bg-green-100 text-green-600 border-green-200", path: "/latihan" }, 
  ]
};

const SEARCHABLE_FEATURES = [ 
  ...MAIN_FEATURES.filter(i => !['media', 'wanita', 'hitung', 'more'].includes(i.id)), 
  ...SUB_FEATURES.media,
  ...SUB_FEATURES.wanita,
  ...SUB_FEATURES.hitung,
  ...SUB_FEATURES.more,
  { icon: Brain, label: "Cerdas Cermat", color: "bg-purple-100 text-purple-600 border-purple-200", path: "/quiz" }, 
  { icon: Book, label: "Kitab Kuning", color: "bg-amber-100 text-amber-600 border-amber-200", path: "/kitab" }, 
  { icon: BookOpen, label: "Al-Quran", color: "bg-emerald-100 text-emerald-600 border-emerald-200", path: "/quran" }, 
  { icon: Scroll, label: "Hadis", color: "bg-blue-100 text-blue-600 border-blue-200", path: "/hadis" }, 
  { icon: Clock, label: "Jadwal Sholat", color: "bg-green-100 text-green-600 border-green-200", path: "/sholat" }, 
  { icon: User, label: "Biografi Ulama", color: "bg-slate-100 text-slate-600 border-slate-200", path: "/biography" }, 
  { icon: Settings, label: "Pengaturan", color: "bg-slate-100 text-slate-600 border-slate-200", path: "/settings" }, 
];

const HIJRI_MONTHS_ID: Record<string, string> = { "Muharram": "Muharram", "Safar": "Safar", "Rabi' al-Awwal": "Rabiul Awal", "Rabi' al-Thani": "Rabiul Akhir", "Jumada al-Ula": "Jumadil Awal", "Jumada al-Akhirah": "Jumadil Akhir", "Rajab": "Rajab", "Sha'ban": "Sya'ban", "Ramadan": "Ramadhan", "Shawwal": "Syawal", "Dhu al-Qi'dah": "Dzulkaidah", "Dhu al-Hijjah": "Dzulhijjah", "Rabi al-Awwal": "Rabiul Awal", "Rabi al-Thani": "Rabiul Akhir", "Jumada al-Awwal": "Jumadil Awal", "Jumada al-Thani": "Jumadil Akhir", "Dhul Qidah": "Dzulkaidah", "Dhul Hijjah": "Dzulhijjah", "Rabiʻ I": "Rabiul Awal", "Rabiʻ II": "Rabiul Akhir" };

const FeatureButton: React.FC<{ item: any, onClick: () => void }> = ({ item, onClick }) => { 
  const Icon = item.icon; 
  const colorStr = item.color || '';
  const colorParts = colorStr.split(' '); 
  const bgClass = colorParts.find((c: string) => c.startsWith('bg-')) || ''; 
  const textClass = colorParts.find((c: string) => c.startsWith('text-')) || ''; 
  const borderClass = colorParts.find((c: string) => c.startsWith('border-')) || ''; 
  return ( 
    <button className="flex flex-col items-center gap-2 group w-full" onClick={onClick}> 
      <div className={`w-14 h-14 rounded-2xl border-2 ${borderClass} ${bgClass} flex items-center justify-center shadow-sm group-hover:scale-105 transition-transform dark:bg-slate-800`}> 
        <Icon size={26} strokeWidth={3} className={textClass} /> 
      </div> 
      <span className="text-[10px] font-bold text-slate-600 dark:text-slate-400 text-center leading-tight"> 
        {item.label} 
      </span> 
    </button> 
  ); 
};

const HomeScreen: React.FC<HomeScreenProps> = ({ fontSize }) => {
  const location = useLocation();
  const navigate = useNavigate();
  const historyRef = useRef<HTMLDivElement>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);
  const { history } = useHistory();
  const { user, loading: authLoading } = useAuth();
  const { showToast } = useToast(); 

  const { prayerData, locationName, nextPrayer, countdown, refreshLocation, loading: prayerLoading } = usePrayer();
  const [searchQuery, setSearchQuery] = useState('');
  const [isSearching, setIsSearching] = useState(false);

  const [surahs, setSurahs] = useState<any[]>([]);
  const [hadiths, setHadiths] = useState<any[]>([]);
  const [doas, setDoas] = useState<any[]>([]);
  const [news, setNews] = useState<any[]>([]);

  const [searchResults, setSearchResults] = useState<{
    features: any[],
    surahs: any[],
    hadiths: any[],
    doas: any[],
    history: any[]
  }>({ features: [], surahs: [], hadiths: [], doas: [], history: [] });

  const [activeSubMenu, setActiveSubMenu] = useState<string | null>(null);
  const [mutiaraItems, setMutiaraItems] = useState<MutiaraData[]>([]);
  const [mutiaraLoading, setMutiaraLoading] = useState(true);
  const [mutiaraError, setMutiaraError] = useState<string | null>(null);
  const [refreshKey, setRefreshKey] = useState(0);
  const [isSharingImage, setIsSharingImage] = useState<string | null>(null);

  const getHijriDate = (d: Date) => {
    try {
      const parts = new Intl.DateTimeFormat('en-u-ca-islamic-umalqura', {
        day: 'numeric', month: 'numeric', year: 'numeric'
      }).formatToParts(d);
      return { 
        day: parseInt(parts.find(p => p.type === 'day')?.value || '1'), 
        month: parseInt(parts.find(p => p.type === 'month')?.value || '1') 
      };
    } catch (e) { return { day: 1, month: 1 }; }
  };

  const eventCountdown = useMemo(() => {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    for (let i = 0; i < 366; i++) {
        const checkDate = new Date(today);
        checkDate.setDate(today.getDate() + i);
        const hijri = getHijriDate(checkDate);
        const event = ISLAMIC_EVENTS.find(e => e.month === hijri.month && e.day === hijri.day);
        if (event) return { name: event.name, days: i };
    }
    return null;
  }, []);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [surahData, hadithData, newsData] = await Promise.all([
            getAllSurahs(), 
            getHadithBooks(),
            fetchNewsReleases(4) 
        ]);
        setSurahs(surahData);
        setHadiths(hadithData);
        setNews(newsData);

        const doaRes = await fetch('https://raw.githubusercontent.com/Kopeahku/hadisku/main/assets/file/doa-harian.json');
        if (doaRes.ok) {
            const doaData = await doaRes.json();
            setDoas(doaData);
        }
      } catch (e) { /* */ }
    };
    fetchData();
  }, []);

  useEffect(() => {
    if (!searchQuery.trim()) { setIsSearching(false); return; }
    setIsSearching(true);
    const q = searchQuery.toLowerCase();

    const matchedFeatures = SEARCHABLE_FEATURES.filter(f => f.label.toLowerCase().includes(q)).slice(0, 3);
    const matchedSurahs = surahs.filter(s => s.name_latin.toLowerCase().includes(q)).slice(0, 3);
    const matchedHadiths = hadiths.filter(h => h.name.toLowerCase().includes(q)).slice(0, 2);
    const matchedDoas = doas.filter(d => d.nama.toLowerCase().includes(q)).slice(0, 3);
    const matchedHist = history.filter(h => h.title.toLowerCase().includes(q) || (h.subtitle && h.subtitle.toLowerCase().includes(q))).slice(0, 3);

    setSearchResults({ 
      features: matchedFeatures, 
      surahs: matchedSurahs, 
      hadiths: matchedHadiths, 
      doas: matchedDoas, 
      history: matchedHist 
    });
  }, [searchQuery, history, surahs, hadiths, doas]);

  useEffect(() => {
    if (location.state && (location.state as any).tab === 'history') {
      setTimeout(() => { historyRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' }); }, 300);
      window.history.replaceState({}, document.title);
    }
  }, [location]);

  // NEW: Fetch Mutiara from Supabase
  useEffect(() => {
    setMutiaraLoading(true); 
    setMutiaraError(null);
    const loadMutiaraData = async () => {
        try {
            const data = await fetchPublicMutiara(4); // Limit to 4 items for home screen
            const textOnly = (data as MutiaraData[]).filter(i => i.type === 'quote');
            const sorted = textOnly.sort((a, b) => new Date(b.date || 0).getTime() - new Date(a.date || 0).getTime());
            setMutiaraItems(sorted); 
        } catch (e) { 
            //
            setMutiaraError("Gagal memuat mutiara."); 
        } finally {
            setMutiaraLoading(false); 
        }
    };
    loadMutiaraData();
  }, [refreshKey]); 

  const handleMutiaraShare = async (item: MutiaraData, e: React.MouseEvent) => {
    e.stopPropagation();
    const cardId = `mutiara-card-${item.id}`;
    const element = document.getElementById(cardId);

    if (!element) {
        const text = item.type === 'quote' ? `"${item.content}" - ${item.scholar}\n\nDibagikan dari SantriAI` : `Tonton Kajian: ${item.title}\n${item.url}`;
        if (navigator.share) await navigator.share({ title: 'Mutiara Ulama', text });
        return;
    }

    setIsSharingImage(item.id || null);
    showToast('Sedang menyiapkan gambar...', 'info');

    try {
        const html2canvas = (window as any).html2canvas;
        if (!html2canvas) throw new Error('html2canvas not loaded');

        const canvas = await html2canvas(element, {
            scale: 2, 
            useCORS: true,
            backgroundColor: null,
            logging: false
        });

        canvas.toBlob(async (blob: Blob | null) => {
            if (!blob) return;

            const file = new File([blob], `Mutiara_${item.scholar.replace(/\s+/g, '_')}.png`, { type: 'image/png' });

            if (navigator.canShare && navigator.canShare({ files: [file] })) {
                try {
                    await navigator.share({
                        files: [file],
                        title: 'Mutiara Ulama',
                        text: `Nasehat dari ${item.scholar}`
                    });
                } catch (shareErr) {
                    //
                }
            } else {
                const url = URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = url;
                a.download = `Mutiara_${item.scholar}.png`;
                a.click();
                showToast('Gambar diunduh (Browser tidak mendukung share file)', 'success');
            }
            setIsSharingImage(null);
        }, 'image/png');

    } catch (err) {
        //
        showToast('Gagal memproses gambar. Membagikan teks saja.', 'warning');
        const text = item.type === 'quote' ? `"${item.content}" - ${item.scholar}` : item.title || '';
        if (navigator.share) await navigator.share({ title: 'Mutiara Ulama', text });
        setIsSharingImage(null);
    }
  };

  const handleAiSearch = () => { if (!searchQuery.trim()) return; navigate('/explanation', { state: { query: searchQuery } }); setSearchQuery(''); setIsSearching(false); };
  const handleRefreshLocation = (e: React.MouseEvent) => { e.stopPropagation(); refreshLocation(); };

  const handleFeatureClick = (item: any) => {
    // FIXED: Pengecekan status login untuk menu Top Santri
    if (item.id === 'top' && !user) {
      showToast("Silakan login terlebih dahulu untuk mengakses Papan Peringkat.", "info");
      navigate('/settings');
      return;
    }

    if (['media', 'wanita', 'hitung', 'more'].includes(item.id)) { 
      setActiveSubMenu(item.id); 
      return; 
    }
    if (item.path) { 
      if (item.path.startsWith('http')) window.open(item.path, '_blank'); 
      else { navigate(item.path); setActiveSubMenu(null); } 
    } 
    else { showToast('Fitur akan segera hadir!', 'info'); }
  };

  const handleOpenQuiz = () => { if (user) navigate('/quiz-pro'); else navigate('/quiz'); };
  const getIndoHijriMonth = (en: string) => HIJRI_MONTHS_ID[en] || en;
  const formatIndoDate = (dateStr?: string) => { if (!dateStr) return ''; const date = new Date(dateStr); return new Intl.DateTimeFormat('id-ID', { day: 'numeric', month: 'long', year: 'numeric' }).format(date); };
  const filteredHistory = history.filter(item => { if (!searchQuery) return true; const q = searchQuery.toLowerCase(); return (item.title.toLowerCase().includes(q) || (item.subtitle && item.subtitle.toLowerCase().includes(q))); });

  return (
    <div className="pb-24 pt-0 min-h-screen flex flex-col bg-slate-50 dark:bg-slate-950 relative">
      <div className="animate-in fade-in slide-in-from-top-4 duration-500">
          <div onClick={() => navigate('/prayer-times')} className="bg-santri-green dark:bg-santri-green-dark text-white shadow-lg mb-0 cursor-pointer active:opacity-90 transition-opacity">
            <div className="grid grid-cols-5 text-center border-b border-white/10">
              {[{ label: 'SUBUH', time: prayerData?.timings.Fajr || '--:--' }, { label: 'DZUHUR', time: prayerData?.timings.Dhuhr || '--:--' }, { label: 'ASHAR', time: prayerData?.timings.Asr || '--:--' }, { label: 'MAGHRIB', time: prayerData?.timings.Maghrib || '--:--' }, { label: 'ISYA', time: prayerData?.timings.Isha || '--:--' }].map((p, i) => { const displayTime = p.time.replace(/\s*\(.*?\)\s*/g, ''); const isNext = p.label === nextPrayer?.name; return ( <div key={i} className={`py-2 pt-5 flex flex-col items-center justify-center transition-colors ${isNext ? 'bg-santri-gold text-santri-green' : ''}`}> <span className={`text-[10px] uppercase font-bold mb-0.5 ${isNext ? 'text-santri-green' : 'text-green-50 opacity-80'}`}>{p.label}</span> <span className={`text-sm ${isNext ? 'font-black text-santri-green' : 'font-bold text-white'}`}>{displayTime}</span> </div> ); })}
            </div>
            <div className="flex justify-between items-center px-4 py-2 bg-santri-green dark:bg-santri-green-dark">
                <div className="flex items-center gap-3"><MapPin size={22} strokeWidth={2} className="text-santri-gold" /><div className="flex flex-col text-left"><span className="text-sm font-bold text-white leading-tight">{locationName}</span><button onClick={handleRefreshLocation} className="text-[10px] text-green-200 font-medium underline decoration-green-300/50 hover:text-white text-left flex items-center gap-1">{prayerLoading ? <Loader2 size={10} className="animate-spin" /> : null} Ganti Lokasi</button></div></div>
                <div className="flex flex-col items-end"><div className="text-xs font-bold text-santri-gold flex items-center gap-1"><span>{prayerData?.date.hijri.day} {getIndoHijriMonth(prayerData?.date.hijri.month.en || '')} {prayerData?.date.hijri.year} H</span><ArrowRight size={14} strokeWidth={3} /></div><span className="text-[10px] text-green-100 font-medium mr-10">{formatIndoDate(prayerData?.date.readable)}</span></div>
            </div>

            <div className="bg-santri-green-dark dark:bg-black/20 border-t border-white/10 overflow-hidden h-11 flex items-center relative">
               <div className="flex whitespace-nowrap animate-marquee">
                 <div className="flex items-center gap-4 px-10">
                    <div className="flex items-center gap-2">
                       <div className="text-santri-gold animate-pulse"><Activity size={18} strokeWidth={3} /></div>
                       <span className="text-xs font-bold tracking-widest uppercase text-white/90">MENUJU {nextPrayer?.name || 'SHOLAT'}</span>
                    </div>
                    <div className="flex items-center gap-2">
                       <span className="font-mono text-xl font-black text-santri-gold tracking-tight">{countdown || "00:00:00"}</span>
                       <span className="bg-white/20 text-white text-[10px] font-bold px-1.5 py-0.5 rounded">WIB</span>
                    </div>
                 </div>

                 {eventCountdown && (
                    <div className="flex items-center gap-4 px-10 border-l border-white/10">
                       <div className="flex items-center gap-2">
                          <div className="text-amber-400"><CalendarClock size={18} strokeWidth={3} /></div>
                          <span className="text-xs font-bold tracking-widest uppercase text-white/90">{eventCountdown.days === 0 ? "HARI INI" : `${eventCountdown.days} HARI LAGI`}</span>
                       </div>
                       <div className="flex items-center gap-2">
                          <span className="text-sm font-black text-santri-gold tracking-tight uppercase">{eventCountdown.name}</span>
                          <div className="p-1 bg-white/20 rounded-full"><Star size={10} className="fill-current text-yellow-300" /></div>
                       </div>
                    </div>
                 )}
               </div>
            </div>
          </div>
      </div>
      <div className="px-4 pt-6">
        <div className="animate-in fade-in slide-in-from-left-4 duration-300">
          {/* Main 8-Box Grid */}
          <div className="mb-6 grid grid-cols-4 gap-4 animate-in fade-in slide-in-from-bottom-2 duration-500 relative z-0">
            {MAIN_FEATURES.map((item, idx) => (
              <FeatureButton key={idx} item={item} onClick={() => handleFeatureClick(item)} />
            ))}
          </div>

          <div className="mb-6 relative group z-50">
            <div className="absolute left-4 top-3.5 text-slate-400 group-focus-within:text-santri-green transition-colors"><Search size={22} strokeWidth={3} /></div>
            <input ref={searchInputRef} type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} onKeyDown={(e) => { if (e.key === 'Enter' && searchQuery.trim()) handleAiSearch(); }} onFocus={() => setIsSearching(!!searchQuery)} placeholder="Cari surat, doa, fitur, atau tanya AI..." className="w-full pl-12 pr-10 py-3.5 bg-white dark:bg-slate-900 rounded-2xl border-2 border-santri-green/60 dark:border-santri-gold focus:outline-none focus:border-santri-green dark:focus:border-santri-gold focus:ring-4 focus:ring-santri-green/10 dark:focus:ring-santri-gold/10 transition-all shadow-sm text-sm font-medium text-slate-800 dark:text-slate-100 placeholder:text-slate-400" />
            {searchQuery && (<button onClick={() => { setSearchQuery(''); setIsSearching(false); }} className="absolute right-3 top-3.5 p-1 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 bg-slate-100 dark:bg-slate-800 rounded-full transition-colors"><X size={16} strokeWidth={3} /></button>)}
            {isSearching && searchQuery && (
              <div className="absolute top-full left-0 right-0 mt-2 bg-white dark:bg-slate-900 rounded-2xl shadow-2xl border-2 border-slate-100 dark:border-slate-800 overflow-hidden max-h-[60vh] overflow-y-auto animate-in fade-in zoom-in-95 duration-200 z-[100] no-scrollbar">
                {searchResults.features.length > 0 && (
                  <div className="p-2 border-b border-slate-50 dark:border-slate-800">
                    <h4 className="text-[10px] font-bold text-slate-400 px-2 py-1 uppercase tracking-widest">Menu</h4>
                    {searchResults.features.map((f, i) => { const Icon = f.icon; return (
                        <button key={i} onClick={() => { navigate(f.path); setSearchQuery(''); setIsSearching(false); }} className="w-full flex items-center gap-3 p-2 hover:bg-slate-50 dark:hover:bg-slate-800 rounded-xl transition-colors text-left">
                          <div className="w-8 h-8 rounded-lg bg-green-100/30"><Icon size={18} strokeWidth={3} className={f.color?.split(' ')[1] || ''} /></div>
                          <span className="text-sm font-bold text-slate-700 dark:text-slate-200">{f.label}</span>
                        </button>
                    );})}
                  </div>
                )}
                {searchResults.surahs.length > 0 && (
                  <div className="p-2 border-b border-slate-50 dark:border-slate-800">
                    <h4 className="text-[10px] font-bold text-emerald-500 px-2 py-1 uppercase tracking-widest">Al-Quran</h4>
