const GlobalListener = ({ onOfflineChange }: { onOfflineChange: (status: boolean) => void }) => {
  const { showToast } = useToast();
  const { loading: authLoading } = useAuth(); 
  const showToastRef = useRef(showToast);
  const lastBroadcastIdRef = useRef<string | null>(null);
  const isFirstLoad = useRef(true);

  const navigate = useNavigate();
  const location = useLocation();

  useEffect(() => {
    showToastRef.current = showToast;
  }, [showToast]);

  useEffect(() => {
    window.handleAndroidBackPress = () => {
      if (location.pathname !== '/') {
        navigate(-1);
        return true; 
      }
      return false; 
    };
    return () => { delete window.handleAndroidBackPress; };
  }, [location, navigate]);

  useEffect(() => {
    const handleOffline = async () => {
      onOfflineChange(true);
      if (db) await db.disableNetwork().catch(console.error);
    };
    const handleOnline = async () => {
      onOfflineChange(false);
      showToastRef.current("Koneksi tersambung kembali.", "success");
      await checkAndAttemptFirebaseNetworkReconnect(showToastRef.current);
    };

    window.addEventListener('offline', handleOffline);
    window.addEventListener('online', handleOnline);

    if (!navigator.onLine) {
       onOfflineChange(true);
    } else {
       checkAndAttemptFirebaseNetworkReconnect(showToastRef.current);
    }

    return () => {
      window.removeEventListener('offline', handleOffline);
      window.removeEventListener('online', handleOnline);
    };
  }, [onOfflineChange]);

  useEffect(() => {
    if (authLoading) return;
    const unsubscribe = subscribeToBroadcasts((data) => {
        if (data.length > 0) {
            const newest = data[0]; 
            if (isFirstLoad.current) {
                lastBroadcastIdRef.current = newest.id as string;
                isFirstLoad.current = false;
                return;
            }
            if (newest.id !== lastBroadcastIdRef.current) {
                lastBroadcastIdRef.current = newest.id as string;
                if (window.AndroidNativeInterface) {
                    window.AndroidNativeInterface.showNotification(
                        newest.title, 
                        newest.message,
                        'broadcast'
                    );
                } else {
                    showToastRef.current(`Info Baru: ${newest.title}`, 'info');
                }
            }
        }
    });
    return () => unsubscribe();
  }, [authLoading]);

  return null;
};

const AppContent: React.FC = () => {
  const { user } = useAuth(); 
  const [isOffline, setIsOffline] = useState(!navigator.onLine);

  const [settings, setSettings] = useState<AppSettings>(() => {
    const saved = localStorage.getItem('santriai_settings');
    const parsed = saved ? JSON.parse(saved) : DEFAULT_SETTINGS;
    return { ...DEFAULT_SETTINGS, ...parsed, supabaseConfig: { ...DEFAULT_SETTINGS.supabaseConfig, ...parsed.supabaseConfig, enabled: true } };
  });

  useEffect(() => {
    if (user) {
      const unsubscribe = subscribeToUserSettings(user.uid, (cloudSettings) => {
        if (cloudSettings) {
          setSettings(prev => ({ 
            ...DEFAULT_SETTINGS, ...prev, ...cloudSettings,    
            supabaseConfig: { ...DEFAULT_SETTINGS.supabaseConfig, ...prev.supabaseConfig, ...cloudSettings.supabaseConfig, enabled: true }
          }));
        }
      });
      return () => unsubscribe();
    } else {
      const saved = localStorage.getItem('santriai_settings');
      const parsed = saved ? JSON.parse(saved) : DEFAULT_SETTINGS;
      setSettings({ ...DEFAULT_SETTINGS, ...parsed, supabaseConfig: { ...parsed.supabaseConfig, enabled: true } });
