  error: Error | null;
}

/**
 * Component to catch and handle runtime errors in the React component tree.
 */
/* Inherit from Component<Props, State> to ensure state and props are correctly typed */
class ErrorBoundary extends Component<Props, State> {
  // Use constructor to ensure proper state and props initialization for the React component
  constructor(props: Props) {
    super(props);
    /* Properly initialize state to resolve "Property 'state' does not exist on type 'ErrorBoundary'" error on line 23 */
    this.state = {
      hasError: false,
      error: null
    };
  }

  /**
   * Updates state so the next render will show the fallback UI.
   */
  public static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  /**
   * Log error details for debugging purposes.
   */
  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error('Uncaught error:', error, errorInfo);
  }

  /**
   * Resets error state and reloads the page.
   */
  /* Reset error status using the setState method inherited from Component, resolving error on line 49 */
  private handleReload = () => {
    // Fix: Using setState method from the base class
    this.setState({ hasError: false, error: null });
    window.location.reload();
  };

  public render(): ReactNode {
    /* Correctly access state and props from the Component instance, resolving errors on lines 55 and 56 */
    const { hasError } = this.state;
    const { children } = this.props;

    if (hasError) {
      return (
        <div className="min-h-screen bg-slate-50 dark:bg-slate-950 flex flex-col items-center justify-center p-6 text-center font-sans">
          <div className="w-24 h-24 bg-red-100 dark:bg-red-900/20 rounded-full flex items-center justify-center mb-6">
            <Tv size={48} className="text-red-500" />
          </div>
          <p className="text-slate-50 dark:text-slate-400 max-w-xs mb-8 text-sm leading-relaxed">
            Untuk mengganti channel, silahkan klik tombol <strong>"Ganti Channel"</strong> dibawah ini
          </p>

          <button
            onClick={this.handleReload}
            className="px-8 py-3.5 bg-santri-green text-white rounded-xl font-bold shadow-lg shadow-green-200 dark:shadow-green-900/20 hover:bg-green-700 active:scale-95 transition-all flex items-center gap-2"
          >
            <RefreshCw size={20} /> Ganti Channel
          </button>
        </div>
      );
    }

    // Render children if no error has occurred
    return children;
  }
}

export default ErrorBoundary;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Sparkles, Search, Quote, Share2, Loader2, RefreshCw, Wand2, Video } from 'lucide-react';
import { fetchPublicMutiara, savePublicMutiara } from '../services/supabaseService';
import { MutiaraData } from '../types';
import { useAuth } from '../contexts/AuthContext';
import { QUOTE_THEMES, generateJson } from '../services/geminiService'; 
import { useToast } from '../contexts/ToastContext'; 
import { useHistory } from '../contexts/HistoryContext'; 
import { PLAYSTORE_LINK } from '../constants';
import { v4 as uuidv4 } from 'uuid'; 

const MutiaraScreen: React.FC = () => {
  const navigate = useNavigate();
  const { showToast } = useToast(); 
  const { addToHistory } = useHistory(); 
  const { user } = useAuth();

  const [items, setItems] = useState<MutiaraData[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [refreshKey, setRefreshKey] = useState(0); 
  const [aiGenerating, setAiGenerating] = useState(false);
  const [isSharingImage, setIsSharingImage] = useState<string | null>(null);
  const isSharingRef = useRef(false);

  useEffect(() => {
    setLoading(true);
    const loadMutiara = async () => {
        try {
            const data = await fetchPublicMutiara();
            const textOnly = (data as MutiaraData[]).filter(i => i.type === 'quote');
            const sorted = textOnly.sort((a, b) => new Date(b.date || 0).getTime() - new Date(a.date || 0).getTime());
            setItems(sorted); 
        } catch (e) {
            showToast("Gagal memuat mutiara.", "error");
            setItems([]);
        } finally {
            setLoading(false); 
        }
    };
    loadMutiara();
  }, [refreshKey, showToast]); 

  const filteredItems = items.filter(item => {
    const term = searchQuery.toLowerCase();
    return (item.scholar && item.scholar.toLowerCase().includes(term)) || 
           (item.content && item.content.toLowerCase().includes(term));
  });

  const handleShareAsImage = async (item: MutiaraData, e: React.MouseEvent) => {
    e.stopPropagation();
    if (isSharingRef.current) return;

    const cardId = `mutiara-card-${item.id}`;
    const element = document.getElementById(cardId);
    if (!element) return;

    setIsSharingImage(item.id || null);
    isSharingRef.current = true;
    showToast('Menyiapkan gambar...', 'info');

    try {
        const html2canvas = (window as any).html2canvas;
        if (!html2canvas) throw new Error('html2canvas not loaded');

        const canvas = await html2canvas(element, {
            scale: 3, 
            useCORS: true,
            backgroundColor: null,
            logging: false,
            onclone: (clonedDoc: Document) => {
                const el = clonedDoc.getElementById(cardId);
                if (el) {
                    // 1. Sembunyikan tombol share
                    const btn = el.querySelector('.share-btn-capture');
                    if (btn) (btn as HTMLElement).style.display = 'none';

                    // 2. Rapikan Teks agar tidak terpotong
                    const textElems = el.querySelectorAll('.text-content-capture');
                    textElems.forEach(t => { 
                        (t as HTMLElement).style.whiteSpace = 'normal'; 
                        (t as HTMLElement).style.overflow = 'visible'; 
                    });

                    // 3. GESER KONTEN KE ATAS: Hilangkan margin atas ikon yang dihapus
                    const contentArea = el.querySelector('.quote-content-area');
                    if (contentArea) {
                        (contentArea as HTMLElement).style.marginTop = '0px';
                        (contentArea as HTMLElement).style.paddingTop = '10px';
                    }

                    // 4. WATERMARK LEBIH SEIMBANG
                    el.style.paddingBottom = '70px'; 

                    const watermark = clonedDoc.createElement('div');
                    watermark.innerText = 'APLIKASI SANTRI AI';
                    watermark.style.cssText = `
                        position: absolute; 
                        bottom: 25px; 
                        left: 0; 
                        width: 100%; 
                        text-align: center; 
                        font-size: 10px; 
                        font-weight: 900; 
                        color: rgba(255,255,255,0.7); 
                        text-transform: uppercase; 
                        letter-spacing: 5px;
                    `;
                    el.appendChild(watermark);
                }
            }
        });

        if (window.AndroidNativeInterface?.shareImage) {
            const base64Image = canvas.toDataURL("image/png");
            window.AndroidNativeInterface.shareImage(base64Image, `Mutiara_${item.scholar.replace(/\s+/g, '_')}.png`);
        } else {
            canvas.toBlob(async (blob) => {
                if (!blob) return;
                const file = new File([blob], `Mutiara.png`, { type: 'image/png' });
                if (navigator.share) await navigator.share({ files: [file], title: 'Mutiara Ulama', text: `${item.content}\n\nNasehat dari ${item.scholar}\n\nDownload Santri AI:\n${PLAYSTORE_LINK}` });
            }, 'image/png');
        }
    } catch (err) { showToast('Gagal memproses gambar.', 'error'); } finally { setIsSharingImage(null); isSharingRef.current = false; }
  };

  const processQuoteGeneration = useCallback(async () => {
    setAiGenerating(true); 
    try {
        const promptText = `Pakar nasehat Islami. Buat 1 mutiara hikmah unik Ulama Aswaja tentang: "${searchQuery}". JSON Output: {"scholar": "...", "role": "...", "content": "...", "theme": "..."}`;
        const res = await generateJson(promptText, "Ahli Hikmah.", true);

        if (res.scholar && res.content) {
            const newItem: MutiaraData = {
                id: uuidv4(),
                type: 'quote',
                scholar: res.scholar,
                role: res.role || 'Ulama',
                content: res.content,
                theme: res.theme || QUOTE_THEMES[Math.floor(Math.random() * QUOTE_THEMES.length)].id,
                date: new Date().toISOString()
            };

            await savePublicMutiara(newItem, user?.uid);
            addToHistory({ id: newItem.id!, type: 'mutiara', title: newItem.scholar, subtitle: `Nasehat tentang ${searchQuery}`, timestamp: newItem.date!, path: '/mutiara', data: newItem });

            showToast("Hikmah baru berhasil terbit!", "success");
            setSearchQuery(''); 
            setRefreshKey(prev => prev + 1); 

            // Trigger Interstitial Ad AFTER success (as requested)
            if (window.AndroidNativeInterface?.showInterstitialAd) {
                window.AndroidNativeInterface.showInterstitialAd();
            }
        }
    } catch (e) { 
        showToast("Gagal memanggil AI.", "error"); 
    } finally { 
        setAiGenerating(false); 
    }
  }, [searchQuery, showToast, user?.uid, addToHistory, setRefreshKey]);

  const initiateQuoteRequest = async () => {
    if (!searchQuery.trim()) {
        showToast("Masukkan topik nasehat", "warning");
        return;
    }
    processQuoteGeneration();
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 pb-24 font-sans">
      <div className="sticky top-0 z-30 bg-white dark:bg-slate-900 border-b border-slate-100 dark:border-slate-800 shadow-sm px-4 py-3 flex items-center justify-between transition-colors">
        <button onClick={() => navigate(-1)} className="p-2 -ml-2 text-slate-600 dark:text-slate-300 rounded-full hover:bg-slate-100 transition-colors"><ArrowLeft size={24} /></button>
        <h2 className="font-bold text-slate-800 dark:text-slate-100 text-lg flex items-center gap-2"><Sparkles size={20} className="text-teal-500" /> Mutiara Ulama</h2>
        <button onClick={() => setRefreshKey(prev => prev + 1)} className="p-2 -mr-2 text-slate-400 hover:text-teal-500 rounded-full transition-colors"><RefreshCw size={20} className={loading ? 'animate-spin' : ''} /></button>
      </div>

      <div className="p-4 max-w-2xl mx-auto space-y-6">

        {/* PANEL AI */}
        <div className="bg-white dark:bg-slate-900 p-5 rounded-[2rem] shadow-lg border border-slate-100 dark:border-slate-800 space-y-4 animate-in slide-in-from-top-4 duration-500">
            <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-teal-100 dark:bg-teal-900/30 rounded-2xl flex items-center justify-center text-teal-600 dark:text-teal-400"><Wand2 size={20} /></div>
                <div><h3 className="font-black text-slate-800 dark:text-slate-100 text-sm">Minta Nasehat AI</h3><p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Berdasarkan topik pilihanmu</p></div>
            </div>
            <div className="relative">
                <Search size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
                <input type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} placeholder="Sabar, Rezeki, Syukur..." className="w-full pl-11 pr-4 py-4 bg-slate-50 dark:bg-slate-800 rounded-2xl outline-none border-2 border-transparent focus:border-teal-500 transition-all text-sm font-medium" onKeyDown={(e) => e.key === 'Enter' && initiateQuoteRequest()} />
            </div>
            <button onClick={initiateQuoteRequest} disabled={aiGenerating || !searchQuery.trim()} className="w-full py-4 bg-gradient-to-r from-teal-500 to-emerald-600 text-white rounded-[1.25rem] font-black text-sm shadow-lg flex items-center justify-center gap-3 active:scale-[0.98] transition-all disabled:opacity-50">
                {aiGenerating ? <Loader2 size={20} className="animate-spin" /> : <Sparkles size={20} />}
                {aiGenerating ? 'MERANGKAI HIKMAH...' : 'BUAT KUTIPAN BARU'}
            </button>
        </div>

        {/* LIST CARDS */}
        <div className="grid grid-cols-1 gap-4">
            {loading ? (
                <div className="flex flex-col items-center justify-center py-20 text-center space-y-4">
                    <Loader2 size={40} className="text-teal-500 animate-spin" />
                    <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">Memuat database hikmah...</p>
                </div>
            ) : filteredItems.length === 0 ? (
                <div className="text-center py-10 bg-slate-100 dark:bg-slate-900/50 rounded-2xl border-2 border-dashed border-slate-200 dark:border-slate-800"><p className="text-slate-400 text-sm italic">Belum ada kutipan.</p></div>
            ) : (
                filteredItems.map((item) => (
                    <div 
                      key={item.id} 
                      id={`mutiara-card-${item.id}`} 
                      className={`p-4 rounded-[1.5rem] border flex flex-col relative overflow-hidden transition-all hover:shadow-lg group ${QUOTE_THEMES.find(t => t.id === item.theme)?.class || QUOTE_THEMES[0].class}`}
                    >
                        <div className="absolute inset-0 opacity-10 bg-[url('https://www.transparenttextures.com/patterns/arabesque.png')] pointer-events-none"></div>

                        <div className="quote-content-area mb-2 relative z-10 flex flex-col items-center text-center justify-center px-2">
                            <p className="text-base md:text-lg font-serif italic leading-relaxed text-white drop-shadow-md py-2">
                                "{item.content}"
                            </p>
                        </div>

                        <div className="flex items-end justify-between mt-auto pt-2 border-t border-white/20 relative z-10">
                            <div className="flex-1 pr-4 text-white">
                                <p className="text-content-capture text-sm font-black leading-tight drop-shadow-sm">{item.scholar}</p>
                                <p className="text-content-capture text-[8px] uppercase font-bold tracking-widest opacity-80 mt-0.5">{item.role}</p>
                            </div>
                            <button 
                                onClick={(e) => handleShareAsImage(item, e)} 
                                disabled={isSharingImage === item.id} 
                                className="share-btn-capture p-2.5 rounded-xl bg-white/20 backdrop-blur-md border border-white/30 text-white shrink-0 active:scale-90 transition-all hover:bg-white/30"
                            >
                                {isSharingImage === item.id ? <Loader2 size={18} className="animate-spin" /> : <Share2 size={18} />}
                            </button>
                        </div>
                    </div>
                ))
            )}
        </div>
      </div>
    </div>
  );
};

export default MutiaraScreen;

