export const translateText = async (text: string): Promise<any> => {
  const cached = await fetchGlobalCache(text, 'translation');
  if (cached) return { ...cached, sourceType: 'AI_CACHE' };

  const result = await callWithRetry(async (ai) => {
    const response = await ai.models.generateContent({
      model: GEMINI_MODEL,
      contents: text,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION + "\n\nOUTPUT MUST BE JSON WITH KEYS: originalText, matan, arabGundul, modernTranslation, maknaGandul, murab, nahwuShorof, munasabah, hikmah, referensi, quranRef, hadithRef, aiExplanation.",
        responseMimeType: "application/json"
      }
    });
    return parseJsonSafely(cleanJson(response.text || "{}"));
  });

  await saveGlobalCache(text, result, 'translation', GEMINI_MODEL);
  return { ...result, sourceType: 'AI_FRESH' };
};

