export const generateNewsAI = async (source: string): Promise<any> => {
  const prompt = `Buatlah artikel berita Islami yang informatif dan terpercaya berdasarkan sumber atau topik berikut: "${source}". 
  Gunakan gaya bahasa jurnalistik Indonesia yang baik. Pastikan isi berita minimal 3 paragraf dan mencakup inti sari serta dampak bagi santri atau umat Islam.

  Output MUST be valid JSON:
  {
    "title": "Judul Berita yang Menarik",
    "excerpt": "Ringkasan berita dalam 1 kalimat",
    "content": "Isi berita lengkap (gunakan karakter \\n untuk baris baru)",
    "category": "Warta/Pesantren/Hikmah/Tekno-Islam/Internasional",
    "grounding_source": "Link rujukan berita asli jika tersedia"
  }`;

  return await callWithRetry(async (ai) => {
    const response = await ai.models.generateContent({
      model: GEMINI_MODEL,
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json"
      }
    });

    const parsed = parseJsonSafely(cleanJson(response.text || "{}"));

    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks && chunks.length > 0 && !parsed.grounding_source) {
       const webChunk = chunks.find((c: any) => c.web);
       if (webChunk) parsed.grounding_source = webChunk.web.uri;
    }

    return parsed;
  });
};

