  const handleBack = () => {
    setView('list');
    setSurahDetail(null);
  };

  const handleBookmark = async (ayah: Ayah) => {
    if (!surahDetail) return;
    const id = `surah-${surahDetail.number}-ayah-${ayah.number}`;
    const exists = bookmarks.find(b => b.id === id);

    if (exists) {
      if (user) await removeUserBookmark(user.uid, id);
      else setBookmarks(prev => prev.filter(b => b.id !== id));
      showToast("Ayat dihapus dari penanda", "info");
    } else {
      const newBookmark: BookmarkItem = {
        id,
        surahNumber: surahDetail.number,
        surahName: surahDetail.name_latin,
        ayah: { ...ayah, surahNumber: surahDetail.number },
        savedAt: new Date().toISOString()
      };
      if (user) await saveUserBookmark(user.uid, 'quran', id, newBookmark);
      else setBookmarks(prev => [newBookmark, ...prev]);
      showToast("Ayat disimpan ke penanda", "success");
    }
  };

  const isBookmarked = (surahNum: number, ayahNum: number) => {
    return bookmarks.some(b => b.id === `surah-${surahNum}-ayah-${ayahNum}`);
  };

  const handleDeleteBookmark = async (id: string) => {
     if (user) await removeUserBookmark(user.uid, id);
     else setBookmarks(prev => prev.filter(b => b.id !== id));
     showToast("Penanda dihapus", "info");
  };

  const openBookmark = (item: BookmarkItem) => {
    const surah = allSurahs.find(s => s.number === item.surahNumber);
    if (surah) handleSurahClick(surah, item.ayah.number);
  };

  const handleCopy = (ayah: Ayah) => {
    const text = `${ayah.arab}\n\n${ayah.text}\n(QS. ${surahDetail?.name_latin}: ${ayah.number})\n\nDownload Aplikasi Santri Modern:\n${PLAYSTORE_LINK}`;
    navigator.clipboard.writeText(text);
    setCopiedId(ayah.id);
    setTimeout(() => setCopiedId(null), 2000);
    showToast("Teks ayat disalin", "success");
  };

  const handleShare = async (ayah: Ayah) => {
    if (isSharing.current) return;
    isSharing.current = true;
    const text = `${ayah.arab}\n\n${ayah.text}\n(QS. ${surahDetail?.name_latin}: ${ayah.number})\n\nDownload Aplikasi Santri Modern:\n${PLAYSTORE_LINK}`;
    const title = `QS. ${surahDetail?.name_latin}: ${ayah.number}`;

    if (window.AndroidNativeInterface?.shareText) {
      try { window.AndroidNativeInterface.shareText(title, text); } catch (error) { handleCopy(ayah); } finally { isSharing.current = false; }
    } else if (navigator.share) {
      try { await navigator.share({ title: title, text: text }); } catch (error: any) { if (error.name !== 'AbortError') handleCopy(ayah); } finally { isSharing.current = false; }
    } else {
      handleCopy(ayah);
      isSharing.current = false;
    }
  };

  const colorizeTajwid = (text: string) => {
    let colored = text;
    colored = colored.replace(/(اللَّهِ|اللَّهُ|اللَّهَ|لِلَّهِ|بِاللَّهِ)/g, '<span class="text-amber-500 font-bold">$1</span>');
    colored = colored.replace(/([ن|م]\u0651)/g, '<span class="text-red-600 font-bold">$1</span>');
    colored = colored.replace(/([ق|ط|ب|ج|د]\u0652)/g, '<span class="text-blue-600 font-bold">$1</span>');
    colored = colored.replace(/([\u0621-\u064A]\u0653)/g, '<span class="text-purple-600 font-bold">$1</span>');
    colored = colored.replace(/(\u06E2|\u06D8)/g, '<span class="text-teal-600 font-bold">$1</span>');
    colored = colored.replace(/([ل|ر]\u0651)/g, '<span class="text-yellow-500 font-bold">$1</span>');
    colored = colored.replace(/(\u064B|\u064C|\u064D)/g, '<span class="text-green-500 font-bold">$1</span>'); 
    colored = colored.replace(/([^\u0646\u0645\u064ل\u0631]\u0651)/g, '<span class="text-fuchsia-500">$1</span>');
    return colored;
  };

  const handlePlayAyah = (ayah: Ayah) => {
      if (currentAyah?.id === ayah.id) togglePlay();
      else if (surahDetail && surahDetail.ayahs) playAyah(surahDetail, ayah, surahDetail.ayahs);
  };

  const handleTools = async (type: 'Tafsir' | 'Asbabun Nuzul' | 'Bedah AI' | 'Munasabah', ayah: Ayah) => {
    const subtitle = `QS. ${surahDetail?.name_latin} Ayat ${ayah.number}`;

    if (type === 'Tafsir') {
      setModalData({ show: true, title: 'Tafsir Kemenag', subtitle, content: '', loading: true, isAi: false });
      try {
        if (!surahDetail) throw new Error("No surah selected");
        const tafsirData = await getTafsir(surahDetail.number);
        const ayatTafsir = tafsirData.find((t: any) => t.ayat === ayah.number);
        setModalData(prev => ({ ...prev, content: ayatTafsir ? ayatTafsir.teks : "Tafsir tidak ditemukan.", loading: false }));
      } catch (e) { setModalData(prev => ({ ...prev, content: "Gagal memuat Tafsir.", loading: false })); }
      return;
    }

    const query = `Surah ${surahDetail?.name_latin} Ayat ${ayah.number}`;
    const originalText = `Teks Arab: ${ayah.arab}\nTerjemahan: ${ayah.text}`;

    // Mapping focus keys for ResultScreen
    const focusMap: Record<string, string> = {
        'Asbabun Nuzul': 'asbab',
        'Munasabah': 'munasabah',
        'Bedah AI': '' // empty means show full grid
    };

    navigate('/result', {
        state: {
            mode: 'kitab',
            query: `${type} - ${query}`,
            source: "Al-Quran",
            originalText: originalText,
            focus: focusMap[type] || ''
        }
    });
  };

  if (view === 'list') {
    return (
      <div className="pb-24 pt-6 px-4 min-h-screen bg-slate-50 dark:bg-slate-950">
        <div className="flex bg-white dark:bg-slate-900 rounded-xl p-1 mb-6 shadow-sm border border-slate-100 dark:border-slate-800 sticky top-4 z-10 transition-colors">
          {['surah', 'juz', 'bookmark'].map((tab) => (
            <button key={tab} onClick={() => setActiveTab(tab as any)} className={`flex-1 py-2 text-sm font-semibold rounded-lg capitalize transition-all ${activeTab === tab ? 'bg-santri-green/10 text-santri-green dark:text-santri-gold' : 'text-slate-400 dark:text-slate-500 hover:text-slate-600 dark:hover:text-slate-400'}`}>{tab}</button>
          ))}
        </div>
        {activeTab === 'surah' && (
          <><div className="bg-white dark:bg-slate-900 px-4 py-3 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm flex items-center gap-3 mb-6 transition-colors"><Search size={20} /><input type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} placeholder="Cari surat..." className="flex-1 bg-transparent outline-none text-slate-800 dark:text-slate-100 placeholder:text-slate-400 text-base" /></div>{loadingList ? (<div className="flex flex-col items-center justify-center py-20"><Loader2 size={32} className="text-santri-green animate-spin mb-4" /><p className="text-slate-400">Memuat data Al-Quran...</p></div>) : (<div className="space-y-3">{filteredSurahs.map((surah) => (<button key={surah.number} onClick={() => handleSurahClick(surah)} className="w-full bg-white dark:bg-slate-900 p-4 rounded-xl border border-slate-100 dark:border-slate-800 shadow-sm hover:shadow-md hover:border-santri-green/30 dark:hover:border-santri-gold/30 transition-all flex items-center justify-between group"><div className="flex items-center gap-4"><div className="w-10 h-10 rounded-lg bg-green-50 dark:bg-green-900/20 text-santri-green dark:text-santri-gold font-bold flex items-center justify-center text-sm group-hover:bg-santri-green group-hover:text-white transition-colors">{surah.number}</div><div className="text-left"><h3 className="font-bold text-slate-800 dark:text-slate-100 text-base">{surah.name_latin}</h3><p className="text-xs text-slate-500 dark:text-slate-400 font-medium">{surah.meaning} • {surah.number_of_ayah} Ayat</p></div></div><div className="text-santri-green dark:text-santri-gold font-arabic text-xl font-bold">{surah.name}</div></button>))}</div>)}</>
        )}
        {activeTab === 'juz' && (
           <div className="space-y-3 animate-in fade-in duration-300">{JUZ_INFO.map((item) => (<button key={item.id} onClick={() => handleJuzClick(item.id)} className="w-full bg-white dark:bg-slate-900 p-4 rounded-xl border border-slate-100 dark:border-slate-800 shadow-sm hover:border-santri-green dark:hover:border-santri-gold transition-all flex items-center justify-between group"><div><h3 className="text-left font-bold text-slate-800 dark:text-slate-100 text-lg">Juz {item.id}</h3><p className="text-left text-xs text-slate-500 dark:text-slate-400 mt-1">{item.range}</p></div><span className="font-arabic text-2xl text-santri-green dark:text-santri-gold group-hover:scale-110 transition-transform">{item.start}</span></button>))}</div>
        )}
        {activeTab === 'bookmark' && (
          <div className="space-y-4 animate-in fade-in duration-300">{bookmarks.length === 0 ? (<div className="text-center py-20 text-slate-400 dark:text-slate-600"><Bookmark size={48} className="mx-auto mb-4 opacity-30" /><p>Belum ada ayat yang disimpan.</p></div>) : (bookmarks.map((item) => (<div key={item.id} className="bg-white dark:bg-slate-900 p-4 rounded-xl border border-slate-100 dark:border-slate-800 shadow-sm relative"><div className="flex justify-between items-start mb-2"><div className="flex items-center gap-2"><span className="px-2 py-0.5 bg-green-50 dark:bg-green-900/20 text-santri-green dark:text-santri-gold text-[10px] font-bold rounded">{item.surahName} : {item.ayah.number}</span><span className="text-[10px] text-slate-400">{new Date(item.savedAt).toLocaleDateString('id-ID')}</span></div><div className="flex items-center gap-2"><button onClick={() => { const text = `${item.ayah.arab}\n\n${item.ayah.text}\n(QS. ${item.surahName}: ${item.ayah.number})\n\nDownload: ${PLAYSTORE_LINK}`; navigator.clipboard.writeText(text); showToast("Disalin", "success"); }} className="text-slate-400 hover:text-slate-600"><Copy size={16} /></button><button onClick={() => handleDeleteBookmark(item.id)} className="text-red-300 hover:text-red-500"><Trash2 size={16} /></button></div></div><p className="font-arabic text-right text-xl text-slate-800 dark:text-slate-100 mb-2 truncate" dir="rtl">{item.ayah.arab}</p><p className="text-xs text-slate-500 dark:text-slate-400 line-clamp-2 mb-3">{item.ayah.text}</p><button onClick={() => openBookmark(item)} className="w-full py-2 bg-slate-50 dark:bg-slate-800 text-slate-600 dark:text-slate-300 rounded-lg text-xs font-bold hover:bg-slate-100 dark:hover:bg-slate-700">Buka Ayat</button></div>)))}</div>
        )}
      </div>
    );
  }

  return (
    <div className="pb-32 pt-0 min-h-screen bg-slate-50 dark:bg-slate-950 relative">
      <div className="sticky top-0 z-30 w-full"><div className="bg-white dark:bg-slate-900 border-b border-slate-100 dark:border-slate-800 shadow-sm px-4 py-3 flex items-center justify-between transition-colors relative z-20"><div className="flex items-center gap-2"><button onClick={handleBack} className="p-2 -ml-2 text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full"><ChevronLeft size={24} /></button><div><h2 className="font-bold text-slate-800 dark:text-slate-100 leading-tight text-base">{surahDetail?.name_latin || selectedSurah?.name_latin}</h2><span className="text-[10px] font-bold text-santri-green dark:text-santri-gold uppercase tracking-wider block mt-0.5">{(surahDetail?.place || selectedSurah?.place || '...')} • {(surahDetail?.number_of_ayah || selectedSurah?.number_of_ayah || '...')} AYAT</span></div></div><button onClick={() => setIsTajwidMode(!isTajwidMode)} className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-xs font-bold border transition-all ${isTajwidMode ? 'bg-green-100 border-green-500 text-green-700 dark:bg-green-900/40 dark:text-green-400 dark:border-green-800 shadow-sm' : 'bg-slate-100 border-transparent text-slate-500 dark:bg-slate-800 dark:text-slate-400 hover:bg-slate-200'}`}><Palette size={16} /><span>Mode Tajwid</span></button></div>
        {isTajwidMode && (<div className="absolute top-full left-0 right-0 bg-white/95 dark:bg-slate-900/95 backdrop-blur-md border-b border-slate-200 dark:border-slate-800 shadow-lg z-10 px-4 py-4 animate-in slide-in-from-top-2 fade-in duration-200"><div className="flex justify-between items-center mb-3"><h3 className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest">KETERANGAN WARNA TAJWID</h3><button onClick={() => setIsTajwidMode(false)} className="p-1 rounded-full bg-slate-100 text-slate-400"><X size={14}/></button></div><div className="grid grid-cols-2 gap-y-2 gap-x-4"><div className="flex items-center gap-2"><span className="w-2.5 h-2.5 rounded-full bg-red-600"></span><span className="text-[10px] font-medium text-slate-600 dark:text-slate-300">Ghunnah</span></div><div className="flex items-center gap-2"><span className="w-2.5 h-2.5 rounded-full bg-green-500"></span><span className="text-[10px] font-medium text-slate-600 dark:text-slate-300">Ikhfa' Haqiqi</span></div><div className="flex items-center gap-2"><span className="w-2.5 h-2.5 rounded-full bg-fuchsia-500"></span><span className="text-[10px] font-medium text-slate-600 dark:text-slate-300">Idgham Bighunnah</span></div><div className="flex items-center gap-2"><span className="w-2.5 h-2.5 rounded-full bg-orange-500"></span><span className="text-[10px] font-medium text-slate-600 dark:text-slate-300">Izhar Halqi</span></div><div className="flex items-center gap-2"><span className="w-2.5 h-2.5 rounded-full bg-blue-600"></span><span className="text-[10px] font-medium text-slate-600 dark:text-slate-300">Qalqalah</span></div><div className="flex items-center gap-2"><span className="w-2.5 h-2.5 rounded-full bg-teal-500"></span><span className="text-[10px] font-medium text-slate-600 dark:text-slate-300">Iqlab</span></div><div className="flex items-center gap-2"><span className="w-2.5 h-2.5 rounded-full bg-yellow-400"></span><span className="text-[10px] font-medium text-slate-600 dark:text-slate-300">Idgham Bilaghunnah</span></div><div className="flex items-center gap-2"><span className="w-2.5 h-2.5 rounded-full bg-purple-600"></span><span className="text-[10px] font-medium text-slate-600 dark:text-slate-300">Mad</span></div></div></div>)}
      </div>
      <div className="px-4 pt-6"><div className="bg-santri-green text-white rounded-3xl p-6 mb-8 text-center relative overflow-hidden shadow-lg"><div className="absolute top-0 left-0 w-full h-full opacity-10 bg-[url('https://www.transparenttextures.com/patterns/arabesque.png')]"></div><div className="relative z-10"><h1 className="font-arabic text-4xl mb-2">{surahDetail?.number !== 9 ? "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ" : "أعُوذُ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيمِ"}</h1><h2 className="font-bold text-xl mb-1">{surahDetail?.name_latin}</h2><p className="text-green-100 text-xs">{surahDetail?.meaning} • {surahDetail?.number_of_ayah} Ayat</p></div></div>
        {loadingDetail ? (<div className="space-y-6">{[1, 2, 3].map(i => (<div key={i} className="animate-pulse"><div className="h-8 bg-slate-200 dark:bg-slate-800 rounded w-full mb-4"></div><div className="h-4 bg-slate-200 dark:bg-slate-800 rounded w-3/4 mb-2"></div></div>))}</div>) : (<div className="space-y-4">{surahDetail?.ayahs?.map((ayah) => { const isPlayingThis = currentAyah?.id === ayah.id && isPlaying; const isCopied = copiedId === ayah.id; const ayahJuz = surahDetail ? getCurrentJuz(surahDetail.number, ayah.number) : 1; return (
                <div key={ayah.id} id={`ayah-${ayah.id}`} className={`scroll-mt-32 transition-all duration-500 rounded-2xl border p-5 shadow-sm mb-4 ${currentAyah?.id === ayah.id ? 'bg-green-50 dark:bg-green-900/10 border-green-200 shadow-md' : 'bg-white dark:bg-slate-900 border-slate-100 dark:border-slate-800'}`}><div className="w-full mb-4 flex justify-between items-center"><div className="w-10 h-10 rounded-full bg-green-100 text-santri-green flex items-center justify-center font-bold text-sm">{ayah.number}</div><span className="px-2 py-1 bg-slate-100 dark:bg-slate-800 rounded-md text-[10px] font-bold text-slate-500 uppercase border border-slate-200">Juz {ayahJuz}</span></div><p className="text-right font-arabic text-3xl leading-[2.6] text-slate-800 dark:text-slate-100 mb-6 px-1" dir="rtl" dangerouslySetInnerHTML={{ __html: (isTajwidMode ? colorizeTajwid(ayah.arab) : ayah.arab) + `<span class="mr-2 text-santri-gold font-serif text-2xl">۝${toArabicNumerals(ayah.number)}</span>` }} /><p className="text-santri-green dark:text-santri-gold font-medium text-sm mb-2 leading-relaxed text-left">{ayah.latin}</p><p className="text-slate-600 dark:text-slate-300 text-sm mb-6 leading-relaxed text-justify">{ayah.text}</p>
                  <div className="flex items-center gap-3 overflow-x-auto no-scrollbar pb-2"><button onClick={() => handlePlayAyah(ayah)} className={`w-10 h-10 rounded-full flex items-center justify-center border transition-all shrink-0 ${isPlayingThis ? 'bg-santri-green text-white' : 'bg-white dark:bg-slate-800 text-slate-500'}`}>{isPlayingThis ? <Pause size={18} fill="currentColor" /> : <Play size={18} className="ml-0.5" />}</button><button onClick={() => handleBookmark(ayah)} className={`w-10 h-10 rounded-full flex items-center justify-center border transition-all shrink-0 ${isBookmarked(surahDetail.number, ayah.number) ? 'bg-green-50 text-santri-green' : 'bg-white dark:bg-slate-800 text-slate-500'}`}><Bookmark size={18} fill={isBookmarked(surahDetail.number, ayah.number) ? "currentColor" : "none"} /></button><button onClick={() => handleCopy(ayah)} className="w-10 h-10 rounded-full flex items-center justify-center border bg-white dark:bg-slate-800 text-slate-500 shrink-0">{isCopied ? <Check size={18} className="text-green-500" /> : <Copy size={18} />}</button><button onClick={() => handleShare(ayah)} className="w-10 h-10 rounded-full flex items-center justify-center border bg-white dark:bg-slate-800 text-slate-500 shrink-0"><Share2 size={18} /></button><button onClick={() => handleTools('Tafsir', ayah)} className="px-4 h-10 rounded-full border border-blue-200 bg-blue-50 text-blue-600 text-xs font-bold flex items-center gap-1.5 whitespace-nowrap"><BookOpen size={14} /> Tafsir</button></div>
                  <div className="flex items-center gap-2 mt-2 overflow-x-auto no-scrollbar pb-2">
                     <button onClick={() => handleTools('Asbabun Nuzul', ayah)} className="px-4 py-2 rounded-lg bg-red-50 text-red-600 text-[11px] font-bold border border-red-100 whitespace-nowrap active:scale-95 transition-transform">Asbabun Nuzul</button>
                     <button onClick={() => handleTools('Munasabah', ayah)} className="px-4 py-2 rounded-lg bg-teal-50 text-teal-600 text-[11px] font-bold border border-teal-100 whitespace-nowrap active:scale-95 transition-transform">Munasabah</button>
                     <button onClick={() => handleTools('Bedah AI', ayah)} className="px-4 py-2 rounded-lg bg-[#FFF9E6] text-amber-600 text-[11px] font-bold border border-amber-200 whitespace-nowrap flex items-center gap-1 active:scale-95 transition-transform"><Sparkles size={14} /> Bedah AI</button>
                  </div>
                </div>
              ); })}</div>)}
      </div>

      {modalData.show && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in">
           <div className="bg-white dark:bg-slate-900 w-full max-w-lg rounded-3xl shadow-2xl flex flex-col max-h-[85vh] border border-slate-100 dark:border-slate-800 animate-in zoom-in-95">
              <div className="flex justify-between items-center p-5 border-b border-slate-100 dark:border-slate-800 shrink-0"><div className="flex items-center gap-3"><div className={`p-2 rounded-full ${modalData.isAi ? 'bg-amber-100 text-amber-600' : 'bg-blue-100 text-blue-600'}`}>{modalData.isAi ? <Sparkles size={20} /> : <BookOpen size={20} />}</div><div><h3 className="font-bold text-slate-800 dark:text-slate-100 text-lg">{modalData.title}</h3>{modalData.subtitle && (<p className="text-xs text-slate-500 dark:text-slate-400">{modalData.subtitle}</p>)}</div></div><button onClick={() => setModalData({ ...modalData, show: false })} className="p-2 bg-slate-50 dark:bg-slate-800 rounded-full text-slate-400 hover:text-slate-600"><X size={20} /></button></div>
              <div className="overflow-y-auto p-6 flex-1">
                {modalData.loading ? (
                  <CustomLoader message={modalData.isAi ? "AI sedang menganalisis ayat..." : "Memuat data..."} />
                ) : (
                  <div className={`prose prose-sm max-w-none text-slate-700 dark:text-slate-300 leading-relaxed text-justify ${modalData.isAi ? 'whitespace-pre-line' : ''}`}>{modalData.content}</div>
                )}
              </div>
              <div className="h-2 shrink-0"></div>
           </div>
        </div>
      )}
    </div>
  );
};

